describe('Product Search by Keyword', () => {
  beforeEach(() => {
    cy.visit('/products');
  });

  it('should display instant search results as user types a keyword', () => {
    // Verify initial page loads with products
    cy.get('[data-testid="product-list"]').should('be.visible');
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);

    // Intercept the search API call
    cy.intercept('GET', '/api/products/search*').as('searchProducts');

    // Type keyword into search input
    cy.get('[data-testid="search-input"]').type('laptop');

    // Wait for the search API call
    cy.wait('@searchProducts');

    // Verify search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);

    // Verify results contain the keyword
    cy.get('[data-testid="product-item"]').first().should('contain', 'laptop');

    // Verify search input retains the value
    cy.get('[data-testid="search-input"]').should('have.value', 'laptop');

    // Verify results are updated with the correct count
    cy.get('[data-testid="result-count"]').should('contain', '1');
  });

  it('should handle empty search input and display no results message', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/products/search*').as('searchProducts');

    // Clear any existing search term
    cy.get('[data-testid="search-input"]').clear();

    // Press enter or trigger search with empty input
    cy.get('[data-testid="search-input"]').type('');
    cy.get('[data-testid="search-button"]').click();

    // Wait for the search API call
    cy.wait('@searchProducts');

    // Verify no results message is displayed
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No products found');

    // Verify product list is empty
    cy.get('[data-testid="product-item"]').should('not.exist');

    // Verify search input is still visible
    cy.get('[data-testid="search-input"]').should('be.visible');
  });
});
